MATCH (v:PlantItem:GateValve {unit_id: '214'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (item:PlantItem {tag: 'P-44501B'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (e:Equipment)-[:measured_by]->(i:PlantItem {loop_tag: 'PI-59035'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (source:PlantItem {tag: 'P-33901B'}), (v:Valve), (e:Equipment)
WHERE EXISTS { (source)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(e) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'P-48601B'}), (b:PlantItem {tag: 'M-48701'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x.tag <> 'BFV-486001')+ (b)
} AS reachable

MATCH (head:ProcessInstrumentationFunction {loop_tag: 'TIAH-170015'})
MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head)
RETURN DISTINCT equipment.tag AS tag ORDER BY tag;
